{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-ve-terminal-mono",
  "title": "Teach an AI CLI Workflow like a Developer-Tools Educator",
  "title_i18n": {
    "en": "Teach an AI CLI Workflow like a Developer-Tools Educator",
    "zh-CN": "像开发者工具讲师一样教 AI CLI 工作流",
    "zh-TW": "像开发者工具讲师一样教 AI CLI 工作流"
  },
  "version": "1.0.0",
  "publishedAt": "2026-06-16T09:32:15Z",
  "description": "Open Design from the CLI: driving the full design workflow with the `od` command — scripted, composable, agent-ready. Built as a decision-grade AI literacy deck for developers, power users.",
  "description_i18n": {
    "en": "Open Design from the CLI: driving the full design workflow with the `od` command — scripted, composable, agent-ready. Built as a decision-grade AI literacy deck for developers, power users.",
    "zh-CN": "像开发者工具讲师一样教 AI CLI 工作流——一份可商业交付的AI 素养 Deck，围绕真实主题、证据链与决策目标组织。",
    "zh-TW": "像开发者工具讲师一样教 AI CLI 工作流——一份可商业交付的AI 素养 Deck，围绕真实主题、证据链与决策目标组织。"
  },
  "license": "MIT",
  "author": {
    "name": "nicobailon",
    "url": "https://github.com/nicobailon"
  },
  "homepage": "https://github.com/nicobailon/visual-explainer",
  "plugin": {
    "repo": "https://github.com/nicobailon/visual-explainer"
  },
  "tags": [
    "community",
    "deck",
    "slides",
    "presentation",
    "dark",
    "terminal",
    "monospace",
    "developer",
    "dual-theme",
    "web",
    "design",
    "brand",
    "visual-system",
    "ve-terminal-mono",
    "ai-literacy",
    "enterprise-ai-copilot-rollout-brief",
    "ai",
    "copilot",
    "workflow",
    "decision-deck",
    "commercial-slide-agent"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "deck",
    "scenario": "ai",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html",
      "motion": "scroll"
    },
    "useCase": {
      "query": {
        "en": "Create \"Teach an AI CLI Workflow like a Developer-Tools Educator\" as a decision-grade AI literacy deck in this template's own visual system. Subject: Open Design from the CLI: driving the full design workflow with the `od` command — scripted, composable, agent-ready. Audience: developers, power users. First ask only for missing essentials: audience, decision target, source-of-truth materials, deadline, and must-keep numbers. Then produce the slide plan, written slides, visual direction, speaker-ready structure, and a critic pass against this rubric: does the deck make AI implementation concrete enough to fund.",
        "zh-CN": "像开发者工具讲师一样教 AI CLI 工作流。像开发者工具讲师一样教 AI CLI 工作流——一份可商业交付的AI 素养 Deck，围绕真实主题、证据链与决策目标组织。 主题：Open Design from the CLI: driving the full design workflow with the `od` command — scripted, composable, agent-ready. 先确认受众、决策目标、素材来源、截止时间和必须保留的数据，再输出叙事主线、页面规划、逐页文案、视觉方向和按评审标准自检的版本。"
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Teach an AI CLI Workflow like a Developer-Tools Educator",
          "title_i18n": {
            "en": "Teach an AI CLI Workflow like a Developer-Tools Educator",
            "zh-CN": "像开发者工具讲师一样教 AI CLI 工作流",
            "zh-TW": "像开发者工具讲师一样教 AI CLI 工作流"
          }
        }
      ]
    },
    "inputs": [
      {
        "name": "topic",
        "label": "Topic",
        "type": "string",
        "required": true,
        "placeholder": "A release review, an architecture deep-dive, a postmortem...",
        "default": "the user's brief"
      },
      {
        "name": "audience",
        "label": "Audience",
        "type": "string",
        "required": true,
        "placeholder": "An engineering team, conference attendees, open-source users...",
        "default": "a technical audience"
      },
      {
        "name": "slideCount",
        "label": "Length",
        "type": "select",
        "required": true,
        "options": [
          "short 5-10 slides",
          "medium 10-20 slides",
          "long 20+ slides"
        ],
        "default": "short 5-10 slides"
      },
      {
        "name": "density",
        "label": "Density",
        "type": "select",
        "required": true,
        "options": [
          "low density / speaker-led",
          "high density / reading-first"
        ],
        "default": "low density / speaker-led"
      }
    ],
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "discovery",
          "atoms": [
            "discovery-question-form"
          ]
        },
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ],
    "category": "ai-literacy"
  }
}
